mapper.select:
SELECT

  o.*, o.note


FROM orders o
LEFT JOIN customers c ON o.customer_id = c.id
LEFT JOIN addresses a ON c.address_id = a.id

  AND o.amount >= #{minAmount}
  AND o.amount <= #{maxAmount}
  AND o.customer_id = #{customerId}

    AND o.status IN
    #{st}


GROUP BY o.id
HAVING SUM(o.amount) > #{threshold}
ORDER BY o.created_at DESC
LIMIT 100 OFFSET #{pageStart}

mapper.update:
UPDATE orders
amount = amount * (1 - #{discount}), updated_by = #{updatedBy}, updated_at = NOW()
WHERE id = #{id}
